// Memoize with an LRU bound, and an in-flight promise cache that evicts rejections.
function memoize(fn, { max = 3, key = (x) => x } = {}) {
  const cache = new Map(); // Map keeps insertion order: first key = least recent
  const wrapped = function (...args) {
    const k = key(...args);
    if (cache.has(k)) {
      const v = cache.get(k);
      cache.delete(k); cache.set(k, v);            // refresh recency
      return v;
    }
    const result = fn.apply(this, args);
    cache.set(k, result);
    if (result && typeof result.then === "function") {
      result.catch(() => cache.delete(k));          // never cache a rejection
    }
    if (cache.size > max) cache.delete(cache.keys().next().value); // evict oldest
    return result;
  };
  wrapped.keys = () => [...cache.keys()];
  return wrapped;
}
