// Debounce and throttle driven by a fake clock, so the output is deterministic.
let now = 0, timers = [];
const setT = (fn, ms) => { const t = { fn, at: now + ms }; timers.push(t); return t; };
const clearT = (t) => { timers = timers.filter((x) => x !== t); };
