  const end = now + ms;
  for (;;) {
    timers.sort((a, b) => a.at - b.at);
    if (!timers.length || timers[0].at > end) break;
    const t = timers.shift(); now = t.at; t.fn();
  }
  now = end;
}
function debounce(fn, wait) {
  let t;
  return (...a) => { clearT(t); t = setT(() => fn(...a), wait); };
}
