  return {
    now: () => now,
    set(fn, ms) { const t = { fn, at: now + ms }; timers.push(t); return t; },
    clear(t) { timers = timers.filter((x) => x !== t); },
    tick(ms) {
      const end = now + ms;
      for (;;) {
        timers.sort((a, b) => a.at - b.at);
        if (!timers.length || timers[0].at > end) break;
        const t = timers.shift(); now = t.at; t.fn();
      }
      now = end;
    },
  };
}
