// Layout thrashing modelled with a counter: reading while "dirty" forces a layout.
class FakeDom {
  constructor(n) {
    this.heights = new Array(n).fill(10);
    this.dirty = false;
    this.layouts = 0;
  }
  read(i) {                         // like offsetHeight
    if (this.dirty) { this.layouts++; this.dirty = false; } // forced synchronous layout
    return this.heights[i];
  }
  write(i, h) { this.heights[i] = h; this.dirty = true; }   // just marks layout dirty
}
const N = 1000;

const a = new FakeDom(N);
for (let i = 0; i < N; i++) a.write(i, a.read(i) + 1);      // read, write, read, write...
console.log("interleaved layouts:", a.layouts);              // about N

const b = new FakeDom(N);
const reads = [];
for (let i = 0; i < N; i++) reads.push(b.read(i));          // all reads first
for (let i = 0; i < N; i++) b.write(i, reads[i] + 1);       // then all writes
b.read(0);                                                   // browser lays out once
console.log("batched layouts:    ", b.layouts);             // 1
console.log("same result:", a.heights.every((h, i) => h === b.heights[i]));

// A small EventEmitter with once, off, unsubscribe and snapshot iteration.
class Emitter {
  constructor() { this.map = new Map(); }
  on(ev, fn) {
    if (!this.map.has(ev)) this.map.set(ev, []);
    this.map.get(ev).push(fn);
    return () => this.off(ev, fn);                 // unsubscribe function
  }
  off(ev, fn) {
    const list = this.map.get(ev);
    if (!list) return;
    for (let i = list.length - 1; i >= 0; i--) {   // remove most recent match
      if (list[i] === fn || list[i].listener === fn) { list.splice(i, 1); break; }
    }
    if (list.length === 0) this.map.delete(ev);    // no empty keys
  }
  once(ev, fn) {
    const w = (...a) => { this.off(ev, w); fn(...a); }; // remove before calling
    w.listener = fn;
    return this.on(ev, w);
  }
  emit(ev, ...args) {
    const list = this.map.get(ev);
    if (!list) return false;
    for (const fn of [...list]) fn(...args);       // snapshot: safe if listeners remove themselves
    return true;
  }
}
