// Search race: slow old response must not overwrite a newer one.
const delays = { "re": 80, "rea": 60, "reac": 10, "react": 20 }; // older queries are slower
function fakeSearch(q, signal) {
  return new Promise((resolve, reject) => {
    const t = setTimeout(() => resolve("results for " + q), delays[q]);
    if (signal) signal.addEventListener("abort", () => { clearTimeout(t); reject(new Error("aborted " + q)); });
  });
}
// Version 1: naive. The last response to arrive wins, which may be stale.
let shown = "";
async function naive(q) { shown = await fakeSearch(q); }
// Version 2: abort the previous request, only the latest can finish.
let controller = null, shown2 = "";
async function safe(q) {
  if (controller) controller.abort();
  controller = new AbortController();
  try { shown2 = await fakeSearch(q, controller.signal); } catch (e) { /* ignore aborts */ }
}
const queries = ["re", "rea", "reac", "react"];
queries.forEach((q, i) => setTimeout(() => { naive(q); safe(q); }, i * 5));
setTimeout(() => {
  console.log("naive shows:", shown);   // stale: the slowest (oldest) response won
  console.log("safe shows: ", shown2);  // always the latest query
}, 300);

